class Solution { private int n,limitDistinct;private int[][] next;private final int[] work=new int[26];private int cut(int start,int changedIndex,int oldLetter,int replacement){System.arraycopy(next[start],0,work,0,26);if(changedIndex>=0&&replacement!=oldLetter){if(work[oldLetter]==changedIndex)work[oldLetter]=next[changedIndex+1][oldLetter];if(changedIndex>=start&&changedIndex<work[replacement])work[replacement]=changedIndex;}Arrays.sort(work);return limitDistinct<26?work[limitDistinct]:n;}public int maxPartitionsAfterOperations(String s,int k){n=s.length();limitDistinct=k;next=new int[n+1][26];Arrays.fill(next[n],n);for(int i=n-1;i>=0;i--){System.arraycopy(next[i+1],0,next[i],0,26);next[i][s.charAt(i)-'a']=i;}int[] suffix=new int[n+1];for(int i=n-1;i>=0;i--){int boundary=cut(i,-1,0,0);suffix[i]=1+(boundary<n?suffix[boundary]:0);}int[] segmentStart=new int[n],prefixPartitions=new int[n];int mask=0,start=0,parts=0;for(int i=0;i<n;i++){int bit=1<<(s.charAt(i)-'a');if(Integer.bitCount(mask|bit)>k){parts++;start=i;mask=bit;}else mask|=bit;segmentStart[i]=start;prefixPartitions[i]=parts;}int answer=suffix[0];for(int i=0;i<n;i++){int oldLetter=s.charAt(i)-'a';for(int replacement=0;replacement<26;replacement++){int firstBoundary=cut(segmentStart[i],i,oldLetter,replacement),candidate;if(firstBoundary<=i){int secondBoundary=cut(i,i,oldLetter,replacement);candidate=prefixPartitions[i]+2+(secondBoundary<n?suffix[secondBoundary]:0);}else candidate=prefixPartitions[i]+1+(firstBoundary<n?suffix[firstBoundary]:0);answer=Math.max(answer,candidate);}}return answer;} }
